import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:quiztion/data/question_repository.dart';
import 'package:quiztion/data/settings_repository.dart';
import 'package:quiztion/main.dart';
import 'package:shared_preferences/shared_preferences.dart';

import 'support/test_database.dart';

// Smoke test for the app. Replaces the default counter test generated by
// `flutter create` (which referenced a non-existent MyApp).
//
// Uses an in-memory SQLite database and mocked SharedPreferences so it does
// not depend on platform plugins.

void main() {
  testWidgets('home screen renders after initialization', (tester) async {
    SharedPreferences.setMockInitialValues({});
    final db = createTestDatabase();
    final repository = QuestionRepository(db);
    final settings = await SettingsRepository.create();

    await tester.pumpWidget(
      QuiztionApp(repository: repository, settings: settings),
    );

    // Initial frame: loading indicator while the seed/initialization runs.
    expect(find.byType(MaterialApp), findsOneWidget);

    // Let the async initialization (seed + reload) complete and settle.
    await tester.pumpAndSettle();

    // The home screen shows the app title and the main feature entries.
    expect(find.text('QUIZtion'), findsOneWidget);
    expect(find.text('Novo quiz'), findsOneWidget);
    expect(find.text('Banco de questões'), findsOneWidget);

    await db.close();
  });
}
